    /**
     * @method
     * @name bitbns#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.OrderBook> fetchOrderBook(Object symbol, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object limit = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            Object request = new java.util.HashMap<String, Object>() {{
                put( "symbol", Helpers.GetValue(market, "id") );
            }};
            if (Helpers.isTrue(!Helpers.isEqual(limit, null)))
            {
                Helpers.addElementToObject(request, "limit", limit); // default 100, max 5000, see https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#order-book
            }
            Object response = (this.wwwGetOrderFetchOrderbook(this.extend(request, parameters))).join();
            //
            //     {
            //         "bids":[
            //             [49352.04,0.843948],
            //             [49352.03,0.742048],
            //             [49349.78,0.686239],
            //         ],
            //         "asks":[
            //             [49443.59,0.065137],
            //             [49444.63,0.098211],
            //             [49449.01,0.066309],
            //         ],
            //         "timestamp":1619172786577,
            //         "datetime":"2021-04-23T10:13:06.577Z",
            //         "nonce":""
            //     }
            //
            Object timestamp = this.safeInteger(response, "timestamp");
            return this.parseOrderBook(response, Helpers.GetValue(market, "symbol"), timestamp);
        }).thenApply(io.github.ccxt.TypedCores::toOrderBook);

    }

    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        //
        //     {
        //         "symbol":"BTC/INR",
        //         "info":{
        //             "highest_buy_bid":4368494.31,
        //             "lowest_sell_bid":4374835.09,
        //             "last_traded_price":4374835.09,
        //             "yes_price":4531016.27,
        //             "volume":{"max":"4569119.23","min":"4254552.13","volume":62.17722344}
        //         },
        //         "timestamp":1619100020845,
        //         "datetime":1619100020845,
        //         "high":"4569119.23",
        //         "low":"4254552.13",
        //         "bid":4368494.31,
        //         "bidVolume":"",
        //         "ask":4374835.09,
        //         "askVolume":"",
        //         "vwap":"",
        //         "open":4531016.27,
        //         "close":4374835.09,
        //         "last":4374835.09,
        //         "baseVolume":62.17722344,
        //         "quoteVolume":"",
        //         "previousClose":"",
        //         "change":-156181.1799999997,
        //         "percentage":-3.446934874943623,
        //         "average":4452925.68
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object timestamp = this.safeInteger(ticker, "timestamp");
        Object marketId = this.safeString(ticker, "symbol");
        Object symbol = this.safeSymbol(marketId, market);
        Object last = this.safeString(ticker, "last");
        return this.safeTicker(new java.util.HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Bitbns.this.iso8601(timestamp) );
            put( "high", Bitbns.this.safeString(ticker, "high") );
            put( "low", Bitbns.this.safeString(ticker, "low") );
            put( "bid", Bitbns.this.safeString(ticker, "bid") );
            put( "bidVolume", Bitbns.this.safeString(ticker, "bidVolume") );
            put( "ask", Bitbns.this.safeString(ticker, "ask") );
            put( "askVolume", Bitbns.this.safeString(ticker, "askVolume") );
            put( "vwap", Bitbns.this.safeString(ticker, "vwap") );
            put( "open", Bitbns.this.safeString(ticker, "open") );
            put( "close", last );
            put( "last", last );
            put( "previousClose", Bitbns.this.safeString(ticker, "previousClose") );
            put( "change", Bitbns.this.safeString(ticker, "change") );
            put( "percentage", Bitbns.this.safeString(ticker, "percentage") );
            put( "average", Bitbns.this.safeString(ticker, "average") );
            put( "baseVolume", Bitbns.this.safeString(ticker, "baseVolume") );
            put( "quoteVolume", Bitbns.this.safeString(ticker, "quoteVolume") );
            put( "info", ticker );
        }}, market);
    }

