    public Object parseOrder(Object order, Object... optionalArgs)
    {
        //
        // createOrder
        //
        //     {
        //         "data": "Successfully placed bid to purchase currency",
        //         "status": 1,
        //         "error": null,
        //         "id": 5424475,
        //         "code": 200
        //     }
        //
        // fetchOpenOrders, fetchOrder
        //
        //    {
        //        "entry_id": 5424475,
        //        "btc": 0.01,
        //        "rate": 2000,
        //        "time": "2021-04-25T17:05:42.000Z",
        //        "type": 0,
        //        "status": 0
        //        "t_rate": 0.45,                       // only stop orders
        //        "trail": 0                            // only stop orders
        //    }
        //
        // cancelOrder
        //
        //    {
        //        "data": "Successfully cancelled the order",
        //        "status": 1,
        //        "error": null,
        //        "code": 200
        //    }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object id = this.safeString2(order, "id", "entry_id");
        Object datetime = this.safeString(order, "time");
        Object triggerPrice = this.safeString(order, "t_rate");
        Object side = this.safeString(order, "type");
        if (Helpers.isTrue(Helpers.isEqual(side, "0")))
        {
            side = "buy";
        } else if (Helpers.isTrue(Helpers.isEqual(side, "1")))
        {
            side = "sell";
        }
        Object data = this.safeString(order, "data");
        Object status = this.safeString(order, "status");
        if (Helpers.isTrue(Helpers.isEqual(data, "Successfully cancelled the order")))
        {
            status = "cancelled";
        } else
        {
            status = this.parseStatus(status);
        }
        final Object finalSide = side;
        final Object finalStatus = status;
        return this.safeOrder(new java.util.HashMap<String, Object>() {{
            put( "info", order );
            put( "id", id );
            put( "clientOrderId", null );
            put( "timestamp", Bitbns.this.parse8601(datetime) );
            put( "datetime", datetime );
            put( "lastTradeTimestamp", null );
            put( "symbol", Bitbns.this.safeString(market, "symbol") );
            put( "timeInForce", null );
            put( "postOnly", null );
            put( "side", finalSide );
            put( "price", Bitbns.this.safeString(order, "rate") );
            put( "triggerPrice", triggerPrice );
            put( "amount", Bitbns.this.safeString(order, "btc") );
            put( "cost", null );
            put( "average", null );
            put( "filled", null );
            put( "remaining", null );
            put( "status", finalStatus );
            put( "fee", new java.util.HashMap<String, Object>() {{
                put( "cost", null );
                put( "currency", null );
                put( "rate", null );
            }} );
            put( "trades", null );
        }}, market);
    }

    /**
     * @method
     * @name bitbns#createOrder
     * @description create a trade order
     * @see https://docs.bitbns.com/bitbns/rest-endpoints/order-apis/version-2/place-orders
     * @see https://docs.bitbns.com/bitbns/rest-endpoints/order-apis/version-1/market-orders-quantity  // market orders
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much of currency you want to trade in units of base currency
     * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {float} [params.triggerPrice] the price at which a trigger order is triggered at
     *
     * EXCHANGE SPECIFIC PARAMETERS
     * @param {float} [params.target_rate] *requires params.trail_rate when set, type must be 'limit'* a bracket order is placed when set
     * @param {float} [params.trail_rate] *requires params.target_rate when set, type must be 'limit'* a bracket order is placed when set
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Order> createOrder(Object symbol, Object type2, Object side2, Object amount, Object... optionalArgs)
    {
        final Object type3 = type2;
        final Object side3 = side2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object type = type3;
            Object side = side3;
            Object price = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            Object triggerPrice = this.safeStringN(parameters, new java.util.ArrayList<Object>(java.util.Arrays.asList("triggerPrice", "stopPrice", "t_rate")));
            Object targetRate = this.safeString(parameters, "target_rate");
            Object trailRate = this.safeString(parameters, "trail_rate");
            parameters = this.omit(parameters, new java.util.ArrayList<Object>(java.util.Arrays.asList("triggerPrice", "stopPrice", "trail_rate", "target_rate", "t_rate")));
            if (Helpers.isTrue(Helpers.isEqual(side, null)))
            {
                throw new ArgumentsRequired((String)Helpers.add(this.id, " createOrder() requires a side argument")) ;
            }
            final Object finalSide = side;
            Object request = new java.util.HashMap<String, Object>() {{
                put( "side", ((String)finalSide).toUpperCase() );
                put( "symbol", Helpers.GetValue(market, "uppercaseId") );
                put( "quantity", Bitbns.this.amountToPrecision(symbol, amount) );
            }};
            if (Helpers.isTrue(Helpers.isEqual(type, "limit")))
            {
                Helpers.addElementToObject(request, "rate", this.priceToPrecision(symbol, price));
            } else
            {
                Helpers.addElementToObject(request, "market", Helpers.GetValue(market, "quoteId"));
            }
            if (Helpers.isTrue(!Helpers.isEqual(triggerPrice, null)))
            {
                Helpers.addElementToObject(request, "t_rate", this.priceToPrecision(symbol, triggerPrice));
            }
            if (Helpers.isTrue(!Helpers.isEqual(targetRate, null)))
            {
                Helpers.addElementToObject(request, "target_rate", this.priceToPrecision(symbol, targetRate));
            }
            if (Helpers.isTrue(!Helpers.isEqual(trailRate, null)))
            {
                Helpers.addElementToObject(request, "trail_rate", this.priceToPrecision(symbol, trailRate));
            }
            Object response = null;
            if (Helpers.isTrue(Helpers.isEqual(type, "limit")))
            {
                response = (this.v2PostOrders(this.extend(request, parameters))).join();
            } else
            {
                response = (this.v1PostPlaceMarketOrderQntySymbol(this.extend(request, parameters))).join();
            }
            //
            //     {
            //         "data":"Successfully placed bid to purchase currency",
            //         "status":1,
            //         "error":null,
            //         "id":5424475,
            //         "code":200
            //     }
            //
            Object parsed = ((Helpers.isTrue((Helpers.isEqual(response, null))))) ? new java.util.HashMap<String, Object>() {{}} : response;
            return this.parseOrder(parsed, market);
        }).thenApply(io.github.ccxt.TypedCores::toOrder);

    }

    /**
     * @method
     * @name bitbns#cancelOrder
     * @description cancels an open order
     * @see https://docs.bitbns.com/bitbns/rest-endpoints/order-apis/version-2/cancel-orders
     * @see https://docs.bitbns.com/bitbns/rest-endpoints/order-apis/version-1/cancel-stop-loss-orders
     * @param {string} id order id
     * @param {string} symbol unified symbol of the market the order was made in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.trigger] true if cancelling a trigger order
     * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Order> cancelOrder(Object id, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbol = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(symbol, null)))
            {
                throw new ArgumentsRequired((String)Helpers.add(this.id, " cancelOrder() requires a symbol argument")) ;
            }
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            Object isTrigger = this.safeBool2(parameters, "trigger", "stop");
            parameters = this.omit(parameters, new java.util.ArrayList<Object>(java.util.Arrays.asList("trigger", "stop")));
            Object request = new java.util.HashMap<String, Object>() {{
                put( "entry_id", id );
                put( "symbol", Helpers.GetValue(market, "uppercaseId") );
            }};
            Object response = null;
            Object tail = ((Helpers.isTrue((Helpers.isEqual(isTrigger, true))))) ? "StopLossOrder" : "Order";
            Object quoteSide = ((Helpers.isTrue((Helpers.isEqual(Helpers.GetValue(market, "quoteId"), "USDT"))))) ? "usdtcancel" : "cancel";
            quoteSide = Helpers.add(quoteSide, tail);
            Helpers.addElementToObject(request, "side", quoteSide);
            response = (this.v2PostCancel(this.extend(request, parameters))).join();
            Object parsed = ((Helpers.isTrue((Helpers.isEqual(response, null))))) ? new java.util.HashMap<String, Object>() {{}} : response;
            return this.parseOrder(parsed, market);
        }).thenApply(io.github.ccxt.TypedCores::toOrder);

    }

